import ipaddress

def infos(cidr):
    r = ipaddress.ip_network(cidr, strict=False)
    return {"réseau": str(r), "masque": str(r.netmask), "diffusion": str(r.broadcast_address), "hôtes": r.num_addresses - 2}

import ipaddress

def diagnostic(ip, prefixe, passerelle):
    reseau = ipaddress.ip_network(ip + "/" + str(prefixe), strict=False)
    adresse = ipaddress.ip_address(ip)
    if adresse in (reseau.network_address, reseau.broadcast_address):
        return "adresse réservée"
    if ip == passerelle:
        return "passerelle identique à l’adresse"
    if ipaddress.ip_address(passerelle) not in reseau:
        return "passerelle hors du réseau"
    return "ok"
